    const form = document.getElementById('contactForm');

    form.addEventListener('submit', (event) => {
        event.preventDefault();

        // Remove existing error states
        const inputs = form.querySelectorAll('input');
        inputs.forEach(input => {
            input.setAttribute('aria-invalid', 'false');
            const errorId = `${input.id}-error`;
            const errorElement = document.getElementById(errorId);
            if (errorElement) {
                errorElement.remove();
            }
            // Reset aria-describedby to just the helper if it exists
            if (input.id === 'phone') {
                input.setAttribute('aria-describedby', 'phone-helper');
            } else {
                input.removeAttribute('aria-describedby');
            }
        });

        const formData = new FormData(form);
        const data = Object.fromEntries(formData.entries());

        let firstInvalidField = null;

        // Simple validation
        if (!data.fullName.trim()) {
            showError('fullName', 'Full Name is required.');
            if (!firstInvalidField) firstInvalidField = document.getElementById('fullName');
        }

        if (!data.email.trim()) {
            showError('email', 'Email Address is required.');
            if (!firstInvalidField) firstInvalidField = document.getElementById('email');
        } else if (!isValidEmail(data.email)) {
            showError('email', 'Please enter a valid email address.');
            if (!firstInvalidField) firstInvalidField = document.getElementById('email');
        }

        if (firstInvalidField) {
            firstInvalidField.focus();
            return;
        }

        // If valid, simulate submission
        console.log('Form submitted successfully:', data);

        // Hide form fields or show success message
        form.querySelectorAll('.form-field, .form-actions, .required-note').forEach(el => el.style.display = 'none');
        const successMessage = document.getElementById('successMessage');
        successMessage.hidden = false;

        form.reset();
    });

    function showError(fieldId, message) {
        const input = document.getElementById(fieldId);
        input.setAttribute('aria-invalid', 'true');

        const errorId = `${fieldId}-error`;
        let errorElement = document.getElementById(errorId);

        if (!errorElement) {
            errorElement = document.createElement('p');
            errorElement.id = errorId;
            errorElement.className = 'error-message';
            errorElement.style.color = 'var(--error-color)';
            errorElement.style.fontSize = '0.75rem';
            errorElement.style.marginTop = '0.375rem';
            errorElement.textContent = `Error: ${message}`;
            input.parentNode.appendChild(errorElement);
        }

        const currentDescribedBy = input.getAttribute('aria-describedby') || '';
        if (!currentDescribedBy.includes(errorId)) {
            input.setAttribute('aria-describedby', currentDescribedBy ? `${currentDescribedBy} ${errorId}` : errorId);
        }
    }

    function isValidEmail(email) {
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    }
});
