    <main class="container">
        <h1>Contact Support</h1>
        <p class="description">Have a question? We're here to help. Fill out the form below and our team will get back to you shortly.</p>
        <form id="contactForm" novalidate>
            <p class="required-note" aria-hidden="true">* Indicates a required field</p>
            <div class="form-field">
                <label for="fullName">Full Name <span class="required" aria-hidden="true">*</span></label>
                <input type="text" id="fullName" name="fullName" required autocomplete="name">
            </div>

            <div class="form-field">
                <label for="email">Email Address <span class="required" aria-hidden="true">*</span></label>
                <input type="email" id="email" name="email" required autocomplete="email">
            </div>

            <div class="form-field">
                <label for="phone">Phone Number (Optional)</label>
                <input type="tel" id="phone" name="phone" autocomplete="tel" aria-describedby="phone-helper">
                <p id="phone-helper" class="helper-text">Format: +1 (555) 000-0000</p>
            </div>

            <div class="form-actions">
                <button type="submit">Submit Request</button>
            </div>
            <div id="successMessage" class="success-message" hidden aria-live="polite">
                Thank you! Your request has been submitted successfully.
            </div>
        </form>
