             box-sizing: border-box;
         }

         body {
             font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
             background-color: var(--bg-page);
             color: var(--text-main);
             line-height: 1.5;
             margin: 0;
             display: flex;
             justify-content: center;
             align-items: center;
             min-height: 100vh;
             padding: 1rem;
         }

         .container {
             background-color: var(--bg-card);
             width: 100%;
             max-width: 480px;
             padding: 2.5rem;
             border-radius: 0.75rem;
             box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
         }

         h1 {
             font-size: 1.875rem;
             font-weight: 700;
             margin-top: 0;
             margin-bottom: 0.5rem;
         }

         .description {
             color: var(--text-muted);
             margin-bottom: 1rem;
         }

         .required-note {
             font-size: 0.875rem;
             color: var(--text-muted);
             margin-bottom: 2rem;
         }

         .form-field {
             margin-bottom: 1.5rem;
         }

         label {
             display: block;
             font-weight: 600;
             margin-bottom: 0.5rem;
             font-size: 0.875rem;
         }

         .required {
             color: var(--error-color);
             margin-left: 0.125rem;
         }

         input {
             width: 100%;
             padding: 0.75rem 1rem;
             border: 1px solid var(--border-color);
             border-radius: 0.5rem;
             font-size: 1rem;
             transition: border-color 0.15s ease-in-out, box-shadow 0.15s ease-in-out;
             background-color: #fff;
         }

         input:focus {
             outline: none;
             border-color: var(--primary-color);
             box-shadow: 0 0 0 3px var(--focus-ring);
         }

         .helper-text {
             margin-top: 0.375rem;
             font-size: 0.75rem;
             color: var(--text-muted);
         }

         .form-actions {
             margin-top: 2rem;
         }

         button {
             width: 100%;
             padding: 0.75rem 1.5rem;
             background-color: var(--primary-color);
             color: white;
             border: none;
             border-radius: 0.5rem;
             font-size: 1rem;
             font-weight: 600;
             cursor: pointer;
             transition: background-color 0.15s ease-in-out;
         }

         button:hover {
             background-color: var(--primary-hover);
         }

         button:focus {
             outline: none;
             box-shadow: 0 0 0 3px var(--focus-ring);
         }

         .success-message {
             margin-top: 1.5rem;
             padding: 1rem;
             background-color: #f0fdf4;
             border: 1px solid #bbf7d0;
             color: #166534;
             border-radius: 0.5rem;
             text-align: center;
             font-weight: 500;
         }

         @media (prefers-reduced-motion: reduce) {
             input, button {
                 transition: none;
             }
         }
     </style>
 </head>
 <body>
     <main class="container">
         <h1>Contact Support</h1>
         <p class="description">Have a question? We're here to help. Fill out the form below and our team will get back to you shortly.</p>
         <form id="contactForm" novalidate>
             <p class="required-note" aria-hidden="true">* Indicates a required field</p>
             <div class="form-field">
                 <label for="fullName">Full Name <span class="required" aria-hidden="true">*</span></label>
                 <input type="text" id="fullName" name="fullName" required autocomplete="name">
             </div>

             <div class="form-field">
                 <label for="email">Email Address <span class="required" aria-hidden="true">*</span></label>
                 <input type="email" id="email" name="email" required autocomplete="email">
             </div>

             <div class="form-field">
                 <label for="phone">Phone Number (Optional)</label>
                 <input type="tel" id="phone" name="phone" autocomplete="tel" aria-describedby="phone-helper">
                 <p id="phone-helper" class="helper-text">Format: +1 (555) 000-0000</p>
             </div>

             <div class="form-actions">
                 <button type="submit">Submit Request</button>
             </div>
             <div id="successMessage" class="success-message" hidden aria-live="polite">
                 Thank you! Your request has been submitted successfully.
             </div>
         </form>
     </main>
     <script>
         document.addEventListener('DOMContentLoaded', () => {
             const form = document.getElementById('contactForm');

             form.addEventListener('submit', (event) => {
                 event.preventDefault();

                 const inputs = form.querySelectorAll('input');
                 inputs.forEach(input => {
                     input.setAttribute('aria-invalid', 'false');
                     const errorId = `${input.id}-error`;
                     const errorElement = document.getElementById(errorId);
                     if (errorElement) {
                         errorElement.remove();
                     }
                     if (input.id === 'phone') {
                         input.setAttribute('aria-describedby', 'phone-helper');
                     } else {
                         input.removeAttribute('aria-describedby');
                     }
                 });

                 const formData = new FormData(form);
                 const data = Object.fromEntries(formData.entries());

                 let firstInvalidField = null;

                 if (!data.fullName.trim()) {
                     showError('fullName', 'Full Name is required.');
                     if (!firstInvalidField) firstInvalidField = document.getElementById('fullName');
                 }

                 if (!data.email.trim()) {
                     showError('email', 'Email Address is required.');
                     if (!firstInvalidField) firstInvalidField = document.getElementById('email');
                 } else if (!isValidEmail(data.email)) {
                     showError('email', 'Please enter a valid email address.');
                     if (!firstInvalidField) firstInvalidField = document.getElementById('email');
                 }

                 if (firstInvalidField) {
                     firstInvalidField.focus();
                     return;
                 }

                 form.querySelectorAll('.form-field, .form-actions, .required-note').forEach(el => el.style.display = 'none');
                 const successMessage = document.getElementById('successMessage');
                 successMessage.hidden = false;

                 form.reset();
             });

             function showError(fieldId, message) {
                 const input = document.getElementById(fieldId);
                 input.setAttribute('aria-invalid', 'true');

                 const errorId = `${fieldId}-error`;
                 let errorElement = document.getElementById(errorId);

                 if (!errorElement) {
                     errorElement = document.createElement('p');
                     errorElement.id = errorId;
                     errorElement.className = 'error-message';
                     errorElement.style.color = 'var(--error-color)';
                     errorElement.style.fontSize = '0.75rem';
                     errorElement.style.marginTop = '0.375rem';
                     errorElement.textContent = `Error: ${message}`;
                     input.parentNode.appendChild(errorElement);
                 }

                 const currentDescribedBy = input.getAttribute('aria-describedby') || '';
                 if (!currentDescribedBy.includes(errorId)) {
                     input.setAttribute('aria-describedby', currentDescribedBy ? `${currentDescribedBy} ${errorId}` : errorId);
                 }
             }

             function isValidEmail(email) {
                 return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
             }
         });
     </script>
 </body>
 </html>

')
